mapper.select:
SELECT status
FROM t_quartz_task_status
WHERE plan_id = #{planId}
  AND data_date = #{dataDate}
ORDER BY COALESCE(update_time, create_time) DESC, id DESC
LIMIT 1

SELECT count(DISTINCT s.plan_id) FROM t_quartz_task_status s WHERE s.status = 3 AND s.data_date = #{dataDate} AND s.plan_id IN
#{id}
AND NOT EXISTS ( SELECT 1 FROM t_quartz_task_status newer_s WHERE newer_s.plan_id = s.plan_id AND newer_s.data_date = s.data_date AND ( COALESCE(newer_s.update_time, newer_s.create_time) > COALESCE(s.update_time, s.create_time) OR ( COALESCE(newer_s.update_time, newer_s.create_time) = COALESCE(s.update_time, s.create_time) AND newer_s.id > s.id ) ) )

mapper.update:
UPDATE t_quartz_task_status
SET status      = #{entity.status},
    msg         = #{entity.msg},
    update_time = #{entity.updateTime},
    end_time    = #{entity.endTime}

    , begin_time = #{entity.beginTime}

WHERE plan_id = #{entity.planId}
  AND data_date = #{entity.dataDate}

UPDATE t_quartz_task_status
SET execute_pool_id = #{entity.executePoolId},
    execute_pool_name = #{entity.executePoolName},
    execute_datasource_id = #{entity.executeDatasourceId},
    execute_datasource_name = #{entity.executeDatasourceName},
    update_time = #{entity.updateTime}
WHERE plan_id = #{entity.planId}
  AND data_date = #{entity.dataDate}
